    std::unique_ptr<Expr> left, right;          // named, typed children
    Binary(std::unique_ptr<Expr> l, std::unique_ptr<Expr> r)
        : left(std::move(l)), right(std::move(r)) {}
    void print() const override { putchar('('); left->print(); right->print(); putchar(')'); }
};

struct Binary;
using Expr = std::variant<IntLit, std::unique_ptr<Binary>>;
struct Binary { Expr left; char op; Expr right; };   // named child fields

void print_tree(const Expr& e) {
    std::visit(overloaded{
        [](const IntLit& i)   { std::cout << i.value; },
        [](const std::unique_ptr<Binary>& b) { print_tree(b->left); print_tree(b->right); }
    }, e);
}
